@prefix schema1: <http://schema.org/> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode <https://example.org/metadata_archive_001> ;
            sh:resultMessage "A dataset declaring CDIF archive distribution conformance should have at least one schema:distribution." ;
            sh:resultPath schema1:distribution ;
            sh:resultSeverity sh:Warning ;
            sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
            sh:sourceShape [ sh:message "A dataset declaring CDIF archive distribution conformance should have at least one schema:distribution." ;
                    sh:minCount 1 ;
                    sh:path schema1:distribution ;
                    sh:severity sh:Warning ] ] .

